                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("INSUFFICIENT_STOCK"));

        assertThat(getProduct(ok).get("reserved").asInt()).isZero();
        assertThat(getProduct(scarce).get("reserved").asInt()).isZero();
